  guest_requests: { title: "Guest requests", subtitle: "Customer assistance routed to the appropriate hotel team.", columns: [{key:"id",label:"Request"},{key:"reservation_id",label:"Reservation"},{key:"request",label:"Guest need"},{key:"department",label:"Routed to"},{key:"priority",label:"Priority"},{key:"created_at",label:"Submitted"},{key:"status",label:"Status"}], fields: [{key:"reservation_id",label:"Reservation ID"},{key:"request",label:"Guest need"},{key:"department",label:"Department",value:"front_desk"},{key:"priority",label:"Priority",value:"normal"},{key:"status",label:"Status",value:"open"}], statuses:["open","in_progress","completed"] },  housekeeping_tasks: { title: "Housekeeping", subtitle: "Assign, prioritize, and complete room care tasks.", columns: [{key:"id",label:"Task"},{key:"room_number",label:"Room"},{key:"task",label:"Service"},{key:"assignee",label:"Assigned to"},{key:"priority",label:"Priority"},{key:"due",label:"Due"},{key:"status",label:"Status"}], fields: [{key:"room_number",label:"Room"},{key:"task",label:"Task",value:"Stayover service"},{key:"assignee",label:"Assignee"},{key:"priority",label:"Priority",value:"normal"},{key:"due",label:"Due",value:"2:00 PM"},{key:"status",label:"Status",value:"pending"}], statuses:["pending","in_progress","completed"] },
  maintenance_orders: { title: "Maintenance", subtitle: "Track repairs from report to resolution.", columns: [{key:"id",label:"Work order"},{key:"room_number",label:"Location"},{key:"issue",label:"Issue"},{key:"category",label:"Category"},{key:"assignee",label:"Technician"},{key:"priority",label:"Priority"},{key:"status",label:"Status"}], fields: [{key:"room_number",label:"Room / location"},{key:"issue",label:"Issue"},{key:"category",label:"Category",value:"General"},{key:"assignee",label:"Technician"},{key:"priority",label:"Priority",value:"normal"},{key:"status",label:"Status",value:"open"}], statuses:["open","in_progress","resolved"] },
